if (n == b.size) {
    return true;  // No change needed
}

if (n < b.size) {
    // Shrink case - just update size
    b.size = n;
    return true;
}

if (data + b.size + alignment <= data + max_size) {
    // Expand in-place case
    b.size = n;
    return true;
}

if (n > max_size) {
    return false;  // Not enough space
}

// Allocate new block
char* new_data = std::align(alignment, n, data + max_size - n, max_size - n);
if (!new_data) {
    return false;
}

// Copy existing data
std::memcpy(new_data, data, b.size);

// Update block and pointer
b.size = n;
p = new_data;
return true;
// END_CODE

